// Nidaan Engine: one Code node that runs the tools, the demo simulator and the dashboard state.
// Data lives in workflow static data, so the workflow must be ACTIVE and use production webhook URLs.
const S = $getWorkflowStaticData('global');
const IST_MS = 5.5 * 3600 * 1000;
const NOW = Date.now();
const AUTO_RETRY_LIMIT = 25000; // settlements above this always go to a human

function seed() {
  return {
    merchants: {
      M001: { id: 'M001', shop: 'Ramesh Kirana Store', owner: 'Ramesh', city: 'Pimpri', last4: '4821', daily_sales: 28000,
        device: { status: 'online', last_seen_min: 1, note: 'Working normally' },
        settlement: { amount: 12000, status: 'delayed', reason: 'Delayed at the bank', retry_ts: null }, technician: null },
      M002: { id: 'M002', shop: 'Sunita Tailors', owner: 'Sunita', city: 'Wakad', last4: '3376', daily_sales: 32000,
        device: { status: 'online', last_seen_min: 1, note: 'Working normally' },
        settlement: { amount: 8500, status: 'settled', reason: null, retry_ts: null }, technician: null },
      M003: { id: 'M003', shop: 'Imran Chai Point', owner: 'Imran', city: 'Chinchwad', last4: '9054', daily_sales: 45000,
        device: { status: 'online', last_seen_min: 1, note: 'Working normally' },
        settlement: { amount: 48000, status: 'held_for_review', reason: 'Flagged for risk review', retry_ts: null }, technician: null }
    },
    fleet: [
      { id: 'F101', shop: 'Gupta Medical', city: 'Pimpri', daily_sales: 21000, offline: false, since: null },
      { id: 'F102', shop: 'Patil Bakery', city: 'Chinchwad', daily_sales: 15500, offline: false, since: null },
      { id: 'F103', shop: 'Shree Mobile', city: 'Akurdi', daily_sales: 12800, offline: false, since: null },
      { id: 'F104', shop: 'Khan Chicken Centre', city: 'Bhosari', daily_sales: 9400, offline: false, since: null },
      { id: 'F105', shop: 'Joshi Stationers', city: 'Nigdi', daily_sales: 6200, offline: false, since: null }
    ],
    caller: 'M001', approvals: [], messages: [], session: {},
    events: [], handovers: [], bookings: [], ring: null, calls: {}
  };
}
if (!S.nidaan || !S.nidaan.merchants || !S.nidaan.fleet) S.nidaan = seed();
let st = S.nidaan;

function tick() {
  Object.values(st.merchants).forEach(m => {
    const s = m.settlement;
    if (s.status === 'processing' && s.retry_ts && NOW - s.retry_ts > 30000) s.status = 'settled'; // demo: lands after 30s
  });
  if (st.ring && NOW - st.ring.ts > 180000) st.ring = null;
}
function addEvent(callId, mid, action, detail, status, extra) {
  st.events.push(Object.assign({ ts: NOW, call_id: callId || '-', merchant_id: mid || '-', action, detail, status: status || 'ok' }, extra || {}));
  if (st.events.length > 300) st.events = st.events.slice(-300);
  if (callId && callId !== '-' && !st.calls[callId]) st.calls[callId] = NOW;
}
const respond = (obj) => ({ route: 'respond', response: obj });
const money = (n) => '₹' + Number(n).toLocaleString('en-IN');

function transcriptText(t) {
  if (!t) return '';
  if (typeof t === 'string') return t;
  if (Array.isArray(t)) return t.map(x => (x && (x.content || x.text)) || JSON.stringify(x)).join('\n');
  return JSON.stringify(t);
}
const squash = (s) => String(s || '').replace(/(\d)[\s\-,.]+(?=\d)/g, '$1');
const callEvents = (callId) => st.events.filter(e => e.call_id === callId && e.action !== 'log_call' && !/^(call_|sim)/.test(e.action));

function handleTool(body) {
  const args = body.args || {};
  const call = body.call || {};
  const dv = call.retell_llm_dynamic_variables || {};
  const tt = transcriptText(call.transcript);
  const fn = body.name;
  const mid = String(args.merchant_id || dv.merchant_id || '').toUpperCase();
  const m = st.merchants[mid];
  st.session = st.session || {};
  // If the platform sends no call id, group events per merchant until that merchant's call is logged.
  const callId = call.call_id || ('auto-' + mid + '-' + (st.session[mid] || 0));
  const say = (obj, text) => respond(Object.assign({ say: text }, obj));

  if (fn === 'log_call') {
    const evs = callEvents(callId);
    let outcome = args.outcome;
    if (!outcome) {
      const has = (a, re) => evs.some(e => e.action === a && (!re || re.test(e.detail)));
      outcome = has('escalate_to_human') ? 'escalated'
        : has('book_technician') ? 'technician_booked'
        : has('retry_settlement', /^Retried/) ? 'resolved_auto' : 'info_only';
    }
    const summary = args.summary || evs.slice(0, 5).map(e => e.detail).join(' > ') || 'Call completed';
    const started = st.calls[callId];
    const dur = started ? Math.round((NOW - started) / 1000) : null;
    addEvent(callId, mid, 'log_call', outcome + ': ' + summary, 'log', { outcome, duration_s: dur });
    st.session[mid] = (st.session[mid] || 0) + 1;
    return say({ logged: true, outcome }, 'Call logged. You can end the call now with a warm goodbye.');
  }
  if (fn === 'get_call_context' || fn === 'get_outbound_context') {
    const outbound = fn === 'get_outbound_context';
    const cid = outbound ? (st.ring ? st.ring.merchant_id : 'M002') : st.caller;
    const cm = st.merchants[cid];
    const reason = outbound ? (st.ring ? st.ring.reason : 'device_offline') : 'merchant_called';
    const cCall = call.call_id || ('auto-' + cid + '-' + (st.session[cid] || 0));
    addEvent(cCall, cid, 'call_connected', outbound ? cm.owner + ' answered the call from Nidaan' : cm.owner + ' called Nidaan', 'ok');
    if (outbound) st.ring = null;
    return say({ merchant_id: cid, merchant_name: cm.owner, shop_name: cm.shop, call_direction: outbound ? 'outbound' : 'inbound', trigger_reason: reason },
      'Call context loaded. The merchant is ' + cm.owner + ' of ' + cm.shop + '. ' + (outbound ? 'You called them because: ' + reason + '.' : 'The merchant called you. Wait for them to describe the problem.'));
  }
  if (!m) { addEvent(callId, mid, fn, 'Unknown merchant id', 'error'); return say({ success: false, error: 'merchant_not_found' }, 'Could not find this merchant. Apologise briefly and hand over to the human team.'); }

  switch (fn) {
    case 'verify_merchant': {
      let ok;
      if (args.last4) ok = String(args.last4).replace(/\D/g, '').slice(-4) === m.last4;
      else ok = squash(tt).includes(m.last4);
      addEvent(callId, mid, fn, ok ? 'Merchant identity verified' : 'Verification failed (digits not matched)', ok ? 'ok' : 'warn');
      return say({ verified: ok, merchant_name: ok ? m.owner : null },
        ok ? 'Identity verified. Continue helping the merchant.'
           : 'Verification failed. Ask for the last four digits of the registered mobile once more. If it fails again, hand over to a human and share no account details.');
    }
    case 'get_device_status': {
      const d = m.device;
      addEvent(callId, mid, fn, d.status === 'offline' ? 'Soundbox OFFLINE (last seen ' + d.last_seen_min + ' min ago)' : 'Soundbox online', d.status === 'offline' ? 'warn' : 'ok');
      return say({ device_status: d.status, last_seen_minutes_ago: d.last_seen_min, note: d.note, technician_already_booked: m.technician },
        d.status === 'offline'
          ? 'Soundbox is OFFLINE, last seen about ' + d.last_seen_min + ' minutes ago (' + d.note + '). Ask once if it is charged and switched on; if it stays silent, offer a technician visit.'
          : 'Soundbox shows ONLINE and working normally. Ask what exactly is wrong; if the problem continues, offer a technician visit.');
    }
    case 'get_settlement_status': {
      const s = m.settlement;
      const needsHuman = s.status === 'held_for_review' || s.amount > AUTO_RETRY_LIMIT;
      addEvent(callId, mid, fn, money(s.amount) + ' settlement: ' + s.status.replace(/_/g, ' '), s.status === 'settled' || s.status === 'processing' ? 'ok' : 'warn');
      const txt = { delayed: 'delayed at the bank. It can be retried now.', processing: 'already being processed and should reach the bank account by tonight.', settled: 'already paid out to the bank account.', held_for_review: 'on hold for a risk review. Do not retry. Hand over to the human team.' }[s.status] || s.status;
      return say({ amount_rupees: s.amount, status: s.status, reason: s.reason, retry_allowed: s.status === 'delayed' && !needsHuman, requires_human: needsHuman },
        'Settlement of ' + s.amount + ' rupees is ' + txt);
    }
    case 'retry_settlement': {
      const s = m.settlement;
      if (s.status === 'delayed' && s.amount <= AUTO_RETRY_LIMIT) {
        s.status = 'processing'; s.retry_ts = NOW;
        addEvent(callId, mid, fn, 'Retried ' + money(s.amount) + ' settlement, now processing', 'ok');
        return say({ success: true, status: 'processing', amount_rupees: s.amount, expected: 'by tonight' },
          'Retry done for ' + s.amount + ' rupees. It is now processing and should reach the bank account by tonight. Confirm this to the merchant.');
      }
      if (s.status === 'processing') return say({ success: false, status: 'processing' }, 'Settlement is already processing and should arrive by tonight. Tell the merchant no retry is needed.');
      if (s.status === 'settled') return say({ success: false, status: 'settled' }, 'Settlement is already paid out. Nothing to retry.');
      addEvent(callId, mid, fn, 'Retry blocked, needs human review', 'warn');
      return say({ success: false, requires_human: true }, 'This settlement cannot be retried automatically. Hand over to the human team.');
    }
    case 'check_technician_slots': {
      const date = new Date(NOW + IST_MS + 86400000).toISOString().slice(0, 10);
      const slots = ['11:00', '15:00', '18:00'].filter(t => !st.bookings.some(b => b.date === date && b.time === t));
      addEvent(callId, mid, fn, 'Slots for tomorrow: ' + (slots.join(', ') || 'none'), 'ok');
      return say({ date, available_slots: slots },
        slots.length ? 'Earliest technician slot is tomorrow (' + date + ') at ' + slots[0] + '. Offer this slot to the merchant and book it if they agree.'
                     : 'No technician slots are free tomorrow. Hand over to the human team.');
    }
    case 'book_technician': {
      let date = String(args.date || ''), time = String(args.time || '');
      if (!date || !time) {
        date = new Date(NOW + IST_MS + 86400000).toISOString().slice(0, 10);
        time = ['11:00', '15:00', '18:00'].find(t => !st.bookings.some(b => b.date === date && b.time === t)) || '';
      }
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time)) return say({ success: false }, 'Booking failed because no valid slot was found. Hand over to the human team.');
      if (st.bookings.some(b => b.date === date && b.time === time)) return say({ success: false, message: 'slot_taken' }, 'That slot is taken. Call check_technician_slots again.');
      const id = 'TK' + (1001 + st.bookings.length);
      st.bookings.push({ id, merchant_id: mid, date, time });
      m.technician = { id, date, time };
      addEvent(callId, mid, fn, 'Technician booked for ' + date + ' at ' + time, 'ok');
      const start = new Date(date + 'T' + time + ':00+05:30');
      const end = new Date(start.getTime() + 30 * 60000);
      return {
        route: 'book',
        response: { say: 'Technician booked for tomorrow (' + date + ') at ' + time + '. Booking id ' + id + '. Confirm the day and time to the merchant.', success: true, booking_id: id, date, time },
        calendar: {
          summary: 'Soundbox repair: ' + m.shop,
          description: 'Merchant: ' + m.owner + ' (' + mid + ')\nIssue: ' + (args.issue || 'Soundbox offline') + '\nBooked by Nidaan (AI)',
          start: start.toISOString(), end: end.toISOString()
        }
      };
    }
    case 'escalate_to_human': {
      const evs = callEvents(callId);
      const s = m.settlement;
      const has2 = (a) => evs.some(e => e.action === a);
      const REASONS = {
        amount_dispute: 'Merchant disputes the settlement amount. The system shows ' + money(s.amount) + ', but the merchant says it is different.',
        schedule_change: 'Merchant cannot take the technician slot Nidaan offered and wants a different time.',
        fraud_or_angry: 'Merchant reported suspected fraud, is upset, or asked to speak to a person.'
      };
      let reasonText, reasonSource;
      if (s.status === 'held_for_review') { reasonText = money(s.amount) + ' settlement is on a risk-review hold, so it needs a human decision. Nidaan cannot retry it.'; reasonSource = 'system'; }
      else if (REASONS[args.reason]) { reasonText = REASONS[args.reason]; reasonSource = 'agent'; }
      else {
        reasonSource = 'inferred';
        reasonText = has2('check_technician_slots') && !has2('book_technician') ? 'A technician slot was offered but not booked.'
          : has2('get_settlement_status') && !has2('retry_settlement') ? 'The settlement could not be fixed automatically.'
          : 'Merchant needs help beyond the automated tools.';
      }
      const issue = args.issue || reasonText;
      const checked = args.checked || evs.map(e => e.detail).join(' > ') || 'Nothing checked yet';
      const tried = args.tried || (evs.filter(e => /^(Retried|Technician)/.test(e.detail)).map(e => e.detail).join(', ') || 'No automatic action taken');
      const tail = tt.slice(-300);
      st.handovers.push({ ts: NOW, call_id: callId, merchant_id: mid, shop: m.shop, owner: m.owner, issue, reason: reasonText, reason_source: reasonSource, checked, tried, urgency: args.urgency || (s.amount > AUTO_RETRY_LIMIT ? 'high' : 'medium'), transcript_tail: tail });
      if (st.handovers.length > 20) st.handovers = st.handovers.slice(-20);
      const needsApproval = s.status === 'held_for_review';
      if (needsApproval && !st.approvals.some(a => a.merchant_id === mid && a.status === 'pending')) {
        st.approvals.push({ id: 'AP' + (101 + st.approvals.length), merchant_id: mid, shop: m.shop, owner: m.owner, amount: s.amount, status: 'pending', ts: NOW });
      }
      st.handovers[st.handovers.length - 1].needs_approval = needsApproval;
      addEvent(callId, mid, fn, 'Handed to human team: ' + issue, 'escalated');
      return say({ success: true }, 'Handed over to the human team with a full summary. Tell the merchant a senior team member will call back soon and they will not need to repeat anything.');
    }
    default:
      return say({ success: false, error: 'unknown_function' }, 'This action is not available. Hand over to the human team.');
  }
}

function handleSim(q) {
  const a = q.action;
  const mid = String(q.merchant_id || '').toUpperCase();
  if (a === 'reset') { S.nidaan = seed(); st = S.nidaan; return respond({ ok: true }); }
  if (a === 'clear_ring') { st.ring = null; return respond({ ok: true }); }
  if (a === 'set_caller') { if (st.merchants[mid]) st.caller = mid; return respond({ ok: true, caller: st.caller }); }
  if (a === 'approve') {
    const ap = st.approvals.find(x => x.merchant_id === mid && x.status === 'pending');
    const m = st.merchants[mid];
    if (!ap || !m) return respond({ ok: false, error: 'nothing_to_approve' });
    ap.status = 'approved';
    m.settlement.status = 'processing'; m.settlement.retry_ts = NOW;
    addEvent('human', mid, 'human_approved', 'Human approved the retry of ' + money(ap.amount), 'ok');
    st.messages.push({ ts: NOW, merchant_id: mid, shop: m.shop, channel: 'SMS and WhatsApp (simulated)', text: 'Namaste ' + m.owner + ' ji, your ' + money(ap.amount) + ' settlement has been approved by our team and will reach your bank account by tonight. - Nidaan, Paytm' });
    return respond({ ok: true });
  }
  if (a === 'offline') {
    const id = mid || 'M002'; const m = st.merchants[id]; if (!m) return respond({ ok: false });
    m.device = { status: 'offline', last_seen_min: 180, note: 'No network for about three hours', since_ts: NOW - 180 * 60000 };
    [95, 70, 55, 40, 25].forEach((mins, i) => { st.fleet[i].offline = true; st.fleet[i].since = NOW - mins * 60000; });
    addEvent('sim', id, 'outage_wave_detected', 'Monitoring: ' + (1 + st.fleet.length) + ' Soundboxes offline, ranked by money at risk', 'warn');
    st.ring = { active: true, merchant_id: id, reason: 'device_offline', ts: NOW };
    addEvent('sim', id, 'device_offline_detected', m.shop + ': Soundbox went OFFLINE', 'warn');
    addEvent('sim', id, 'outbound_call_started', 'Nidaan is calling the merchant first', 'ok');
    return respond({ ok: true });
  }
  if (a === 'delay') {
    const id = mid || 'M001'; const m = st.merchants[id]; if (!m) return respond({ ok: false });
    m.settlement = { amount: 12000, status: 'delayed', reason: 'Delayed at the bank', retry_ts: null };
    addEvent('sim', id, 'settlement_delay_detected', m.shop + ': ' + money(12000) + ' settlement delayed', 'warn');
    return respond({ ok: true });
  }
  if (a === 'call_started') {
    const id = mid || '-'; const cid = q.call_id || ('web-' + NOW);
    st.calls[cid] = NOW;
    if (q.direction === 'outbound') st.ring = null;
    addEvent(cid, id, 'call_connected', (q.direction === 'outbound' ? 'Merchant answered Nidaan' : 'Merchant called Nidaan'), 'ok');
    return respond({ ok: true });
  }
  if (a === 'call_ended') {
    addEvent(q.call_id || '-', mid || '-', 'call_ended', 'Call ended', 'ok');
    return respond({ ok: true });
  }
  return respond({ ok: false, error: 'unknown_action' });
}

function handleState() {
  const logs = st.events.filter(e => e.action === 'log_call');
  const by = o => logs.filter(l => l.outcome === o).length;
  const durs = logs.map(l => l.duration_s).filter(n => typeof n === 'number');
  const metrics = {
    calls: logs.length,
    auto_resolved: by('resolved_auto') + by('technician_booked'),
    escalated: by('escalated'),
    avg_resolution_s: durs.length ? Math.round(durs.reduce((x, y) => x + y, 0) / durs.length) : null
  };
  const queue = [];
  Object.values(st.merchants).forEach(m => { if (m.device.status === 'offline') queue.push({ id: m.id, shop: m.shop, city: m.city, daily_sales: m.daily_sales, since: m.device.since_ts || (NOW - m.device.last_seen_min * 60000), fixed: !!m.technician, calling: !!st.ring && st.ring.merchant_id === m.id, kind: 'live' }); });
  st.fleet.forEach(f => { if (f.offline) queue.push({ id: f.id, shop: f.shop, city: f.city, daily_sales: f.daily_sales, since: f.since, fixed: false, calling: false, kind: 'fleet' }); });
  return respond({ server_time: NOW, merchants: Object.values(st.merchants), events: st.events.slice(-80), handovers: st.handovers.slice(-5), metrics, ring: st.ring,
    caller: st.caller, queue, approvals: st.approvals.filter(a => a.status === 'pending'), messages: st.messages.slice(-5) });
}

tick();
const inp = $input.first().json;
const body = inp.body || {};
const q = inp.query || {};
let out;
if (body.name && body.args !== undefined) out = handleTool(body);
else if (q.name) out = handleTool({ name: q.name, args: { merchant_id: q.merchant_id, last4: q.last4, date: q.date, time: q.time, issue: q.issue, reason: q.reason, outcome: q.outcome, summary: q.summary }, call: { call_id: q.call_id, transcript: q.transcript } });
else if (q.fn === 'sim') out = handleSim(q);
else out = handleState();
tick();
return [{ json: out }];
